use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input.as_array().unwrap();
    let quantum = input.as_i64().unwrap();

    let mut indices = Vec::new();
    let mut current_work = 0;

    for (index, job) in jobs.iter().enumerate() {
        let job_value = job.as_i64().unwrap();
        if job_value > 0 {
            current_work += job_value;
            indices.push(index);
        }
    }

    indices.sort_unstable_by(|a, b| current_work.cmp(&indices[b]));

    serde_json::Value::Array(indices)
}
